css:
/* Shared native editor shell (ADR-011 §7). Chrome uses neutral greys; only the canvas follows the charte. */
:root{--sh-bg:#fff;--sh-bg2:#f6f7f9;--sh-line:#dde1e6;--sh-ink:#1d2a35;--sh-mute:#5f6b75;--sh-hover:#eceff3;--sh-press:#dfe6ef;--sh-focus:#2563eb;--sh-sel:#e8eefb;--sh-ok:#1f7a4d;--sh-warn:#9a5b00;--sh-err:#b42318}
.sh-root,.sh-pop,.sh-dialog{font:13px/1.3 system-ui,-apple-system,"Segoe UI",Arial,sans-serif;color:var(--sh-ink);box-sizing:border-box}
.sh-root *,.sh-pop *,.sh-dialog *{box-sizing:border-box}
.sh-root :focus-visible,.sh-pop :focus-visible,.sh-dialog :focus-visible{outline:2px solid var(--sh-focus);outline-offset:1px}
/* Host pages may style bare elements; neutralise them inside the shell. */
:is(.sh-root,.sh-pop,.sh-dialog) button{box-shadow:none;letter-spacing:normal;text-transform:none}
:is(.sh-root,.sh-pop) :is(h1,h2,p){margin:0}
.sh-ic{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.sh-car{width:12px;height:12px;margin-left:-2px;opacity:.65}
.sh-root{background:var(--sh-bg)}
.sh-row{display:flex;align-items:center;gap:4px;min-width:0;padding:0 8px 0 10px;height:44px}
.sh-row2{height:40px;background:var(--sh-bg2);border-top:1px solid var(--sh-line);border-bottom:1px solid var(--sh-line);padding:0 4px}
.sh-spacer{flex:1 1 auto;min-width:8px}
.sh-ident{display:flex;align-items:center;gap:10px;min-width:0;flex:0 1 auto;margin-right:6px}
.sh-mark{width:26px;height:26px;border-radius:6px;display:grid;place-items:center;color:#fff;font-weight:700;flex:none;background:var(--sh-ok)}
.sh-tt{display:flex;flex-direction:column;min-width:0}
.sh-title{font-weight:600;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:320px}
.sh-state{display:flex;gap:6px;font-size:11px;color:var(--sh-mute);white-space:nowrap;overflow:hidden;max-width:min(520px,40vw)}
.sh-state>*{overflow:hidden;text-overflow:ellipsis;margin:0;min-width:0}
.sh-state>*:empty{display:none}
.sh-state>*+*::before{content:"· "}
.sh-b{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:5px;height:30px;min-width:30px;padding:0 6px;border:1px solid transparent;border-radius:6px;background:none;color:inherit;font:inherit;cursor:pointer;white-space:nowrap;flex:none}
.sh-b:hover:not(:disabled){background:var(--sh-hover)}
.sh-b:disabled{opacity:.4;cursor:default}
.sh-b[aria-pressed=true],.sh-b[aria-expanded=true]{background:var(--sh-press);border-color:#c9d3df}
.sh-t{padding:0 9px}
.sh-sm{height:26px;min-width:26px}
.sh-g{font:14px/1 Georgia,"Times New Roman",serif;min-width:14px;text-align:center}
.sh-g sub,.sh-g sup{font:9px system-ui,sans-serif}
.sh-primary{background:var(--sh-ink);color:#fff;border-color:var(--sh-ink)}
.sh-primary:hover:not(:disabled){background:#30404d}
.sh-pick{border:1px solid var(--sh-line);background:var(--sh-bg);height:28px;justify-content:space-between;padding:0 6px 0 9px;font-size:12.5px;min-width:100px}
.sh-grp{display:flex;align-items:center;gap:1px;padding:0 6px;border-left:1px solid var(--sh-line);flex:none}
.sh-grp:first-child,.sh-spacer+.sh-grp{border-left:0}
.sh-only-narrow{display:none!important}
.vh{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* toolbar: one tab stop, horizontal scroll with pointer-only overflow arrows */
.sh-tbar{display:flex;align-items:center;min-width:0;flex:1 1 auto;height:100%}
.sh-tscroll{position:relative;display:flex;align-items:center;overflow-x:auto;scrollbar-width:none;flex:1 1 auto;min-width:0;height:100%}
.sh-tscroll::-webkit-scrollbar{display:none}
.sh-ovf{display:none;flex:none;width:22px;height:30px;border:0;background:var(--sh-bg2);font-size:18px;color:var(--sh-mute);cursor:pointer;border-radius:4px}
.sh-tbar.over .sh-ovf{display:block}
.sh-tbar.over.at-start .sh-ovl,.sh-tbar.over.at-end .sh-ovr{visibility:hidden}
/* menubar and menus; popovers sit above every product layer (Slides and Text chrome reach 4200) */
.sh-menubar{display:flex;align-items:center;flex:none}
.sh-mb{height:28px;padding:0 9px;border:0;background:none;border-radius:6px;cursor:pointer;font:inherit;color:inherit}
.sh-mb:hover,.sh-mb[aria-expanded=true]{background:var(--sh-hover)}
.sh-pop{position:fixed;z-index:5000;background:#fff;border:1px solid var(--sh-line);border-radius:8px;box-shadow:0 10px 28px rgba(16,24,40,.16);padding:4px;min-width:200px;overflow:auto}
.sh-menu{list-style:none;margin:0;padding:0}
.sh-menu [role^=menuitem]{display:flex;align-items:center;gap:6px;padding:6px 10px 6px 4px;border-radius:5px;cursor:pointer;white-space:nowrap}
.sh-menu [role^=menuitem]:hover,.sh-menu [role^=menuitem]:focus{background:var(--sh-sel);outline:0}
.sh-menu [aria-disabled=true]{color:#9aa4ad;cursor:default}
.sh-mcheck{width:18px;display:inline-flex}
.sh-mcheck .sh-ic{width:15px;height:15px}
.sh-mic{width:18px;display:inline-flex;flex:none}
.sh-menu kbd{margin-left:auto;padding-left:16px;font:11px system-ui;color:var(--sh-mute)}
.sh-msep{height:1px;background:var(--sh-line);margin:4px 6px}
.sh-mhead{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--sh-mute);padding:8px 10px 4px}
/* context chip and floating settings bar (Slides, Text): status and view controls over the canvas */
.sh-chip{flex:none;margin:0 4px 0 6px;padding:2px 7px;border-radius:10px;background:#e7eef8;color:#1e4f91;font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap}
.sh-float{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);z-index:30;display:flex;align-items:center;gap:2px;padding:4px;border:1px solid var(--sh-line);border-radius:12px;box-shadow:0 4px 16px rgba(16,24,40,.14)}
.sh-fsep{width:1px;height:20px;background:var(--sh-line);margin:0 4px;flex:none}
.sh-finfo{font-size:12px;color:var(--sh-mute);padding:0 8px;white-space:nowrap}
/* colour buttons and swatches */
.sh-colour{flex-direction:column;gap:0;padding:2px 6px}.sh-colour .sh-swbar{display:block;width:16px;height:3px;border-radius:1px;margin-top:1px;border:1px solid var(--sh-line)}
.sh-g b,.sh-g i{font-family:Arial,sans-serif}
.sh-sw:hover{filter:brightness(.9)}
.sh-ghost{border-color:var(--sh-line);background:var(--sh-bg)}
.sh-pop-h{margin:6px 6px 6px;font-size:11px;color:var(--sh-mute)}
.sh-pop-n{margin:8px 6px 2px;font-size:11px;color:var(--sh-mute)}
.sh-pop-sw,.sh-pop-borders{min-width:0}
.sh-swrow{display:flex;gap:6px;padding:0 6px 4px}
.sh-sw{width:24px;height:24px;border-radius:50%;border:1px solid rgba(0,0,0,.22);cursor:pointer;padding:0}
.sh-sw[aria-checked=true]{box-shadow:0 0 0 2px #fff,0 0 0 4px var(--sh-focus)}
.sh-swrow .sh-sw-ink,.sh-swrow .sh-sw-dark{background:var(--ink,#0B1C2C)}.sh-swrow .sh-sw-acc{background:var(--acc,#14517A)}.sh-swrow .sh-sw-mid{background:var(--mid,#4F7FA3)}.sh-swrow .sh-sw-lig{background:var(--lig,#AFC5D4)}
.sh-swrow .sh-sw-alert{background:var(--alert,#C2521C)}.sh-swrow .sh-sw-t2{background:var(--t2,#5A6670)}.sh-swrow .sh-sw-bg{background:var(--bg,#fff)}.sh-swrow .sh-sw-tint{background:var(--tint,#ECEFF2)}
.sh-swrow .sh-sw-none{background:linear-gradient(135deg,#fff 44%,#C2521C 44%,#C2521C 56%,#fff 56%)}
@media (max-width:719.98px){
  .sh-only-narrow{display:inline-flex!important}
  .sh-menubar,.sh-wide{display:none!important}
  .sh-title{max-width:44vw}
  .sh-state{max-width:44vw}
  .sh-float{left:8px;right:8px;bottom:8px;transform:none;justify-content:center}
  /* Visually hidden, still the accessible name. */
  .sh-row .sh-t .sh-lbl{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
}
@media print{.sh-root,.sh-pop,.sh-dialog,.sh-drawer{display:none!important}}
/* Shared side panel (ADR-011 §7), a bottom sheet when narrow, and the document-settings body (theme and font).
   Load after shell.css; every product with document settings uses it. */
.sh-prow{display:flex;flex-wrap:wrap;gap:6px;margin:8px 6px 4px}
.sh-drawer{position:fixed;top:calc(var(--sh-top,96px) + 8px);right:8px;bottom:calc(var(--sh-bottom,0px) + 8px);width:340px;z-index:40;background:var(--sh-bg);border:1px solid var(--sh-line);border-radius:10px;box-shadow:0 12px 32px rgba(16,24,40,.18);overflow:hidden;font:13px/1.3 system-ui,-apple-system,"Segoe UI",Arial,sans-serif;color:var(--sh-ink)}
.sh-drawer[hidden]{display:none}.sh-drawer *{box-sizing:border-box}.sh-drawer :focus-visible{outline:2px solid var(--sh-focus);outline-offset:1px}
.sh-panel{display:flex;flex-direction:column;height:100%}
.sh-ph{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;padding:12px 10px 10px 16px;border-bottom:1px solid var(--sh-line)}
.sh-ph h2{font-size:14px;margin:0;outline:0}.sh-ph p{margin:2px 0 0;font-size:11.5px;color:var(--sh-mute)}
.sh-pb{padding:12px 16px 20px;overflow:auto;flex:1 1 auto}
.sh-pb h3{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--sh-mute);margin:18px 0 8px}.sh-pb h3:first-child{margin-top:2px}
.sh-hint{font-size:11.5px;color:var(--sh-mute);margin:8px 0 0;line-height:1.4}
.sh-themes{display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:8px}
.sh-themes>button{border:1px solid var(--sh-line);border-radius:8px;background:#fff;padding:8px;text-align:left;display:flex;flex-direction:column;gap:4px;cursor:pointer;font:inherit;font-size:12px;font-weight:600;color:inherit}
.sh-dots{display:flex;gap:3px}.sh-dots i{width:13px;height:13px;border-radius:50%;border:1px solid rgba(0,0,0,.12)}
.sh-fonts{display:flex;flex-direction:column;gap:2px}
.sh-fonts>button{display:flex;align-items:center;gap:6px;width:100%;padding:7px 10px;border:1px solid transparent;border-radius:6px;background:none;font-size:14px;text-align:left;cursor:pointer;color:inherit}
.sh-fonts>button:hover{background:var(--sh-hover)}.sh-aa{margin-left:auto;color:var(--sh-mute)}
.sh-themes>button:hover{background:var(--sh-bg2)}
.sh-themes>[aria-checked=true],.sh-fonts>[aria-checked=true]{border-color:var(--sh-focus);box-shadow:0 0 0 2px rgba(37,99,235,.22)}
@media (max-width:719.98px){
  .sh-drawer{top:auto;left:0;right:0;bottom:0;width:auto;height:62vh;border-radius:14px 14px 0 0}
}
/* Shared shell panels (ADR-011 §7): link card, border picker, dialogs and the Data panel bodies
   (cell styles, regional settings). Load after shell.css and drawer.css; products without these components leave it out. */
.sh-link-target{margin:0 6px;max-width:320px;overflow-wrap:anywhere;font-size:12.5px}
.sh-bpresets{display:grid;grid-template-columns:repeat(4,32px);gap:2px;padding:0 4px}
.sh-seg{display:inline-flex;border:1px solid var(--sh-line);border-radius:6px;overflow:hidden;margin:0 6px}
.sh-seg button{display:inline-flex;align-items:center;gap:6px;border:0;background:#fff;padding:4px 10px;font:inherit;font-size:12px;cursor:pointer}
.sh-seg button+button{border-left:1px solid var(--sh-line)}
.sh-seg [aria-checked=true]{background:var(--sh-sel);color:#1e4f91}
.sh-line{display:inline-block;width:18px;border-top:1px solid currentColor}
.sh-line-medium{border-top-width:2px}.sh-line-double{border-top:3px double currentColor;height:0}
.sh-fld{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--sh-mute);margin:8px 0}
.sh-fld input,.sh-fld select{height:30px;border:1px solid var(--sh-line);border-radius:6px;padding:0 8px;background:#fff;color:var(--sh-ink);font:inherit;font-size:13px}
.sh-fld input[aria-invalid=true]{border-color:#b42318}
.sh-err{margin:0;min-height:14px;font-size:11.5px;color:#b42318}
.sh-two{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.sh-two[hidden],.sh-dialog [hidden]{display:none}
.sh-dialog{border:1px solid var(--sh-line);border-radius:12px;padding:0;width:min(440px,calc(100vw - 24px));box-shadow:0 20px 50px rgba(16,24,40,.25)}
.sh-dialog::backdrop{background:rgba(16,24,40,.32)}
.sh-dialog form{padding:18px 20px}
.sh-dialog h2{font-size:16px;margin:0 0 10px}
.sh-radios{border:0;padding:0;margin:0 0 6px;display:flex;gap:16px;flex-wrap:wrap}
.sh-radios legend{font-size:12px;color:var(--sh-mute);padding:0;margin-bottom:6px}
.sh-chk,.sh-dialog label.sh-chk{display:flex;flex-direction:row;gap:6px;align-items:center;font-size:13px}
.sh-dialog .sh-fld label{display:block}
.sh-actions{display:flex;gap:6px;margin-top:14px;align-items:center}
.sh-kv{width:100%;border-collapse:collapse;font-size:12.5px;margin:10px 0}
.sh-kv caption{text-align:left;font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--sh-mute);padding-bottom:6px}
.sh-kv th{text-align:left;font-weight:500;color:var(--sh-mute);padding:5px 0;border-bottom:1px solid var(--sh-line)}.sh-kv td{text-align:right;padding:5px 0;border-bottom:1px solid var(--sh-line)}
.sh-style-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.sh-style-grid>button{border:1px solid var(--sh-line);border-radius:8px;background:#fff;padding:6px;text-align:left;display:flex;flex-direction:column;gap:3px;cursor:pointer;font:inherit;color:inherit}
.sh-style-grid>button:hover{background:var(--sh-bg2)}
.sh-style-grid>[aria-checked=true]{border-color:var(--sh-focus);box-shadow:0 0 0 2px rgba(37,99,235,.22)}
.sh-st-prev{display:block;height:26px;line-height:24px;padding:0 8px;font-family:var(--font,Arial,sans-serif);font-size:13px;color:var(--ink);background:var(--bg);border:1px solid #edf0f3;overflow:hidden;white-space:nowrap}
.sh-st-name{font-size:12px;font-weight:600;padding:0 2px}.sh-st-desc{font-size:10.5px;color:var(--sh-mute);padding:0 2px}
.sh-cs-header{background:var(--header-bg,var(--ink));color:var(--header-ink,var(--bg));font-weight:700}.sh-cs-title{color:var(--acc);font-weight:700}
.sh-cs-rowHeader{color:var(--row-label-ink,var(--acc));background:var(--row-label-bg,var(--tint))}.sh-cs-assumption{background:var(--assumption-bg,var(--callout));color:var(--assumption-ink,var(--alert))}
.sh-cs-calculation{background:var(--calculation-bg,var(--tint))}.sh-cs-output{font-weight:700;box-shadow:inset 0 0 0 1px var(--ink)}
.sh-cs-total{font-weight:700;border-top:1px solid var(--ink);border-bottom:3px double var(--ink)}.sh-cs-note{font-style:italic;color:var(--t2)}
.sh-cs-alert{font-weight:700;color:var(--alert)}.sh-cs-hyperlink{color:var(--acc);text-decoration:underline}
/* html-data page: variant A shell layout (ADR-011 §7); chrome in neutral greys, the grid follows the charte. */
:root{--blue:var(--ink);--light:var(--row-label-bg,color-mix(in srgb,var(--lig) 35%,var(--bg)));--yellow:var(--assumption-bg,var(--callout));--orange:var(--assumption-ink,var(--alert));--border:var(--bd);--muted:var(--t2);--grid-line:#e3e6ea;--head-bg:#f6f7f9;--head-ink:#5f6b75;--head-sel:#e3e9f5;--select:#2563eb}
[hidden]{display:none!important}*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:#fff;color:var(--ink);font-family:var(--font);font-size:14px;overflow:hidden}
.app{display:flex;flex-direction:column;height:100vh;height:100dvh}.app-bar{flex:none}
.sh-state p{font-size:inherit}
/* Formula bar: one 36 px row. */
.formula-bar{display:flex;align-items:center;gap:6px;height:36px;padding:0 8px;border-bottom:1px solid var(--sh-line);background:#fff;flex:none;min-width:0}
.formula-bar input,.formula-bar select{height:26px;border:1px solid var(--sh-line);border-radius:5px;padding:0 6px;background:#fff;color:var(--sh-ink);font:12.5px system-ui,-apple-system,"Segoe UI",Arial,sans-serif;min-width:0}
.formula-bar .name-box{width:76px;flex:none;font-weight:600;font-family:ui-monospace,Menlo,monospace}
.formula-bar #cell-type{width:84px;flex:none;color:var(--sh-mute)}
.fx{font:italic 600 14px Georgia,"Times New Roman",serif;color:var(--sh-mute);padding:0 2px;flex:none}
.formula-bar #cell-value{flex:1 1 48px;min-width:40px;font-family:ui-monospace,Menlo,monospace}
.formula-bar #apply{height:26px;min-width:28px}
.dropdown-control{display:flex;align-items:center;gap:6px;flex:0 1 auto;min-width:0}.dropdown-control[hidden]{display:none}
.dropdown-control label{font-size:12px;color:var(--sh-mute);white-space:nowrap}
.dropdown-control select{max-width:180px;min-width:96px}.dropdown-control select[aria-invalid=true]{border-color:var(--sh-err)}
/* A dropdown note is shown under the bar only when there is something to say. */
.dropdown-control small{position:absolute;left:0;right:0;top:100%;z-index:20;padding:3px 10px;font-size:11.5px;color:var(--sh-warn);background:#fff8e6;border-bottom:1px solid #f0d77a}
.dropdown-control small:empty{display:none}
.formula-bar{position:relative}
.calc{display:flex;align-items:center;gap:4px;flex:none}
#calc-state{display:inline-flex;align-items:center;gap:4px;font-size:12px;white-space:nowrap;padding:0 4px;color:var(--sh-mute)}
#calc-state[data-tone=ok]{color:var(--sh-ok)}#calc-state[data-tone=ok]::before{content:"✓"}
#calc-state[data-tone=warn]{color:var(--sh-warn)}#calc-state[data-tone=warn]::before{content:"!";font-weight:700}#calc-state[data-tone=busy]::before{content:"…"}
.calc .sh-b{height:26px;font-size:12px;border-color:var(--sh-line)}
/* Grid */
.canvas{flex:1 1 auto;min-height:0;display:flex;margin:0}
#grid{flex:1 1 auto;min-width:0;height:auto;position:relative;isolation:isolate;overflow:auto;overscroll-behavior:contain;outline:0;font-size:var(--data-font-size,13px)}
#grid:focus-visible{box-shadow:inset 0 0 0 2px var(--select)}
.grid-plane{position:relative}.grid-row,.grid-cell,.grid-row-head,.grid-column-head,.grid-corner{position:absolute}
.grid-cell{display:flex;align-items:flex-end;justify-content:flex-end;border:0 solid var(--grid-line);border-width:0 1px 1px 0;border-radius:0;margin:0;padding:0 6px;background:var(--bg);color:var(--ink);font:inherit;line-height:22px;text-align:right;overflow:hidden;cursor:cell}
/* Text sits at the bottom (ADR-012 §6); general alignment is resolved per value. */
.grid-cell[data-align=left]{justify-content:flex-start;text-align:left}.grid-cell:is([data-align=center],[data-align=centerContinuous]){justify-content:center;text-align:center}
.cell-text{display:block;min-width:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:pre}
.grid-cell.wrap .cell-text{white-space:pre-wrap;overflow-wrap:anywhere;text-overflow:clip;max-height:100%}
.grid-cell.overflow{overflow:visible;z-index:1}.grid-cell.overflow .cell-text{position:absolute;bottom:0;max-width:none;pointer-events:none}
.grid-edges{position:absolute;inset:0;pointer-events:none;z-index:1}.grid-edge{position:absolute;width:0;height:0}
.grid-cell[aria-selected=true]{box-shadow:inset 0 0 0 999px color-mix(in srgb,var(--select) 10%,transparent)}
.grid-cell[aria-pressed=true]{outline:2px solid var(--select);outline-offset:-2px;box-shadow:none}
.grid-row-head,.grid-column-head,.grid-corner{background:var(--head-bg);color:var(--head-ink);border:0 solid var(--sh-line);border-width:0 1px 1px 0;font:11px/22px system-ui,-apple-system,"Segoe UI",Arial,sans-serif;text-align:center}
.grid-row-head{z-index:2}.grid-column-head,.grid-corner{z-index:3}
.grid-corner{pointer-events:none}.grid-row-head,.grid-column-head{cursor:default}#grid.over-edge .grid-column-head{cursor:col-resize}
.resize-guide{position:absolute;width:0;border-left:2px solid var(--select);z-index:4;pointer-events:none}
.picture-probe{position:absolute;left:-100000px;top:0;visibility:hidden;pointer-events:none}.measure-probe{position:absolute;left:-10000px;top:0;visibility:hidden;line-height:22px;font-size:inherit;overflow-wrap:anywhere;pointer-events:none}
.csv-warning{color:var(--alert);font-weight:600}
.grid-row-head.in-selection,.grid-column-head.in-selection{background:var(--head-sel);color:var(--select);font-weight:600}
.grid-cell:disabled{opacity:1;cursor:wait}
#grid.no-grid-lines .grid-cell{border-color:transparent}
.header{background:var(--header-bg,var(--ink));color:var(--header-ink,var(--bg));font-weight:bold}.rowHeader{background:var(--light);color:var(--row-label-ink,var(--acc))}.assumption{background:var(--yellow);color:var(--orange)}.calculation{background:var(--calculation-bg,var(--tint))}
#grid table{border-collapse:collapse}#grid th,#grid td{border:1px solid var(--grid-line);padding:0}#grid td button{border:0;background:none;height:22px;padding:0 6px;font:inherit}
